sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
        // MSSCUSTODY-6121
        var business = [],type = [],
        gr = new GlideRecord('x_hsb11_mss_unst_0_mss_unstructured_instruction_assignment_routing_rule');
        gr.addEncodedQuery('active=true^assignment_groupDYNAMICd6435e965f510100a9ad2572f2b47744');
        gr.query();
        while (gr.next()) {
            type.push(gr.getValue('instructiontype'));
            business.push(gr.getValue('businessregion'));
        }
        var arrayUtil = new global.ArrayUtil();
        var taskQuery1 = 'instruction_case.owning_businessIN' + arrayUtil.unique(business) + '^instruction_case.instruction_typeIN' + arrayUtil.unique(type);
      //  var query = 'assignment_groupDYNAMICd6435e965f510100a9ad2572f2b47744';
      //  var mergedQuery = query + '^NQ' + taskQuery1 + "^" + current.getEncodedQuery();
        current.addEncodedQuery(taskQuery1);

})(current, previous);
